def make_set(comment):
    lines = [f"                    <!-- {comment} -->"]
    for name, uri in logos:
        lines.append(f'                    <img src="{uri}" alt="{name}" width="40" height="40">')
    return "\n".join(lines)

new_div = f'''                <div class="tool-logos">
{make_set("Set 1")}

{make_set("Set 2 - duplicate for seamless scroll loop")}

{make_set("Set 3 - third copy for wide screens")}

                </div>'''

pattern = r'<div class="tool-logos">.*?</div>'
result = re.sub(pattern, new_div, content, count=1, flags=re.DOTALL)

with open(file_path, 'w', encoding='utf-8') as f:
    f.write(result)

print("SUCCESS: Replaced all logos with inline SVG data URIs")
